function trainingGestureModel(gesture, stroke) {
  const span = stroke === 'SERVE_FAST' ? .34 : { short: .10, medium: .16, long: .28 }[gesture.length] || .16;
  let points;
  if (gesture.kind === 'tap') points = [[0, 0]];
  else if (gesture.radius) {
    const sign = gesture.kind === 'curveLeft' ? -1 : 1;
    points = Array.from({ length: 13 }, (_, i) => {
      const angle = gesture.arcAngle * i / 12;
      return [sign * gesture.radius * Math.cos(angle), gesture.radius * Math.sin(angle)];
    });
  }
  else if (gesture.kind === 'curveLeft' || gesture.kind === 'curveRight') {
    const sign = gesture.kind === 'curveLeft' ? 1 : -1;
    points = Array.from({ length: 17 }, (_, i) => {
      const t = i / 16, u = 1 - t;
      return [sign * span * (.55 * (u * u * u + t * t * t) - 1.2 * u * t + .1625),
        -span * (.5 * u * u * u + 1.5 * u * u * t - 1.5 * u * t * t - .5 * t * t * t)];
    });
  } else {
    const brush = gesture.verticalBrush || 0;
    const [x, y] = gesture.kind === 'up' ? [0, -1] : gesture.kind === 'down' ? [.18, 1]
      : gesture.kind === 'side' ? [Math.sqrt(1 - brush * brush), -brush] : [1, -.20];
    const start = gesture.length === 'short' || stroke === 'CHOP' || stroke === 'SERVE_FAST' ? .8 : .6;
    points = [[-x * span * start, -y * span * start], [0, 0], [x * span * (1 - start), y * span * (1 - start)]];
  }
  // The contact prefix must already describe the stroke, not a curve drawn later.
  const contactIndex = gesture.kind === 'tap' ? 0 : gesture.contactIndex ?? (points.length > 3 ? 10 : 1);
  const anchor = points[contactIndex];
  points = points.map(p => [p[0] - anchor[0], p[1] - anchor[1]]);
  const distance = points.slice(1).reduce((sum, p, i) => sum + Math.hypot(p[0] - points[i][0], p[1] - points[i][1]), 0);
  const beforeContact = points.slice(1, contactIndex + 1).reduce((sum, p, i) => sum + Math.hypot(p[0] - points[i][0], p[1] - points[i][1]), 0);
  const speed = stroke === 'SERVE_FAST' ? 4.6 : { soft: .8, medium: 1.9, fast: 2.9 }[gesture.pace] || 1.9;
  return { ...gesture, points, contact: [0, 0], contactIndex, contactPhase: distance ? beforeContact / distance : 0,
    duration: gesture.kind === 'tap' ? 180 : Math.round(distance / speed * 1000) };
}

