for (const [id, ru, en] of TRAIN_COMMON) trainingText(id, ru, en);
TRAIN_ANSWERS.waitServe = trainingText('answer.waitServe', 'Отдельным новым тапом, когда подброс законно падает', 'With a separate new tap on the legal toss descent');
TRAIN_STEPS[0].tip = 'academy.tapTip'; TRAIN_STEPS[0].mouseTip = 'academy.tapMouseTip';

function trainingGuideView(id) {
  const row = TRAIN_GUIDES[id] || TRAIN_GUIDES.DRIVE;
  const view = { id: row.id, stroke: row.stroke, technique: row.id, gesture: trainingGestureModel(row.gesture, row.stroke),
    brief: { touch: ET(row.briefTouch), mouse: ET(row.briefMouse) }, controls: { touch: ET(row.touch), mouse: ET(row.mouse) } };
  for (const field of ['title', 'feature', 'advantage', 'when', 'risk', 'counter']) view[field] = ET(row[field]);
  const lesson = TRAIN_STEPS.find(s => (s.technique || s.stroke) === row.id && s.check && s.check.strokes && s.check.strokes.length === 1);
  view.lessonId = lesson ? lesson.id : 'HIT';
  return view;
}
function trainingLessonView(step) {
  const guide = trainingGuideView(step.technique || step.stroke);
  if (step.gesture) guide.gesture = trainingGestureModel(step.gesture, step.stroke);
  if (step.check && step.check.tap && !step.serve) {
    guide.gesture = trainingGestureModel({ kind: 'tap', length: 'short', pace: 'soft' });
    guide.brief = { touch: ET('academy.tapTip'), mouse: ET('academy.tapMouseTip') };
    guide.controls = { touch: ET('academy.tapControl'), mouse: ET('academy.tapMouseControl') };
    guide.feature = ET('academy.tapFeature'); guide.advantage = ET('academy.tapAdvantage');
    guide.when = ET('academy.tapWhen'); guide.risk = ET('academy.tapRisk');
  }
  return { ...guide, id: step.id, stroke: step.stroke, technique: step.technique || step.stroke, module: step.module, skills: step.skills.slice(),
    title: ET(step.title), goal: ET(step.goal), context: ET(step.context), need: step.need,
    feed: Object.keys(TRAIN_FEEDS).find(id => TRAIN_FEEDS[id] === step.feed) || null,
    quiz: { prompt: ET(step.quiz.prompt), options: step.quiz.options.map(id => ({ id,
      text: TRAIN_GUIDES[id] ? ET(TRAIN_GUIDES[id].title) : ET(TRAIN_ANSWERS[id]) })) } };
}
function trainingCoverage(lessons) {
  const learned = new Set();
  for (const step of TRAIN_STEPS) if (lessons && Object.prototype.hasOwnProperty.call(lessons, step.id) &&
      lessons[step.id] && lessons[step.id].mastered === true) step.skills.forEach(id => learned.add(id));
  const have = TRAIN_SKILLS.filter(s => learned.has(s.id)).length;
  return { have, total: TRAIN_SKILLS.length, percent: Math.round(have / TRAIN_SKILLS.length * 100) };
}
function trainingCatalog() {
  const covered = new Set(TRAIN_STEPS.flatMap(s => s.skills));
  return { version: TRAINING_VERSION, modules: TRAIN_MODULES.map(m => ({ id: m.id, title: ET(m.title), description: ET(m.description) })),
    skills: TRAIN_SKILLS.map(s => ({ id: s.id, title: ET(s.title) })), lessons: TRAIN_STEPS.map(trainingLessonView),
    strokes: Object.keys(TRAIN_GUIDES).filter(id => TRAIN_GUIDES[id].stroke === id).map(trainingGuideView), targets: TRAIN_TARGETS.map(t => ({ id: t.id, title: ET(t.title) })),
    coverage: Math.round(TRAIN_SKILLS.filter(s => covered.has(s.id)).length / TRAIN_SKILLS.length * 100) };
}
